#!/usr/bin/env node
/**
 * Generates amplify-config.js for local development.
 * 
 * In deployed containers the config is generated at start by frontend/docker-entrypoint.sh
 * from the Deployment's env vars (frontend/openshift.deploy.yml).
 * 
 * This script creates a local dev version with localhost defaults.
 * The generated file is gitignored and should not be committed.
 */

const fs = require('fs');
const path = require('path');

const outputPath = path.join(__dirname, '..', 'public', 'amplify-config.js');

// Check if file already exists
if (fs.existsSync(outputPath)) {
    console.log('amplify-config.js already exists, skipping generation.');
    console.log('Delete the file and re-run this script to regenerate.');
    process.exit(0);
}

const config = `/**
 * Runtime Amplify configuration.
 * 
 * This file is loaded via <script> tag BEFORE the React app starts.
 * In deployed containers, frontend/docker-entrypoint.sh regenerates this file at start.
 * 
 * For local development, this file contains localhost defaults.
 * It is gitignored and auto-generated by npm start if missing.
 */
window.amplifyConfig = {
    appEnv: 'DEV',
    Auth: {
        Cognito: {
            region: 'ca-central-1',
            userPoolId: 'ca-central-1_UpeAqsYt4',
            userPoolClientId: '4dlm5mossuo9d5630a0btbkqq0',
            context: '',
            loginWith: {
                oauth: {
                    domain: 'lza-prod-fam-user-pool-domain.auth.ca-central-1.amazoncognito.com',
                    scopes: ['openid'],
                    redirectSignIn: ['http://localhost:3000/'],
                    redirectSignOut: [
                        'http://localhost:3000/logout',
                    ],
                    responseType: 'code',
                },
            },
        },
    },
};
`;

fs.writeFileSync(outputPath, config, 'utf8');
console.log('Generated amplify-config.js for local development.');
